async function mapped<T>(work:()=>Promise<T>):Promise<T>{try{return await work();}catch(e){if(e instanceof ResignationJourneyError)throw e;const state=pgSqlState(e);if(state==='42501')forbidden();if(state==='40001'||state==='23505')throw new ResignationJourneyError('conflict','This resignation changed or another case is already open. Refresh and try again.');if(e instanceof Error&&e.name==='SigningError'&&'code' in e&&['forbidden','conflict'].includes(String(e.code)))throw new ResignationJourneyError(e.code as 'forbidden'|'conflict',e.message);if(state==='22023'||(e instanceof Error&&['V9Error','SigningError'].includes(e.name)))invalid(e instanceof Error?e.message:'The action could not be completed.');throw e;}}
async function context(tx:Tx,ctx:SessionContext,employmentId:string,caseId:string|null=null):Promise<Context>{await prepareResignationProofTx(tx,ctx,{operation:'context',caseId:caseId??undefined,args:{employmentId,caseId}});const[r]=await tx.execute<{data:Context}>(sql`select app.resignation_journey_context(${employmentId}::uuid,${caseId}::uuid) as data`);if(!r?.data)throw new ResignationJourneyError('not_found','The employee record is unavailable.');return r.data;}
async function rowTx(tx:Tx,id:string,lock=false):Promise<Row>{assertId(id);const rows=await tx.execute<Row>(sql`select *,submitted_on::text,closed_on::text,number::text from resignation_journey where tenant_id=app.current_tenant_id() and id=${id}::uuid ${lock?sql`for update`:sql``}`);if(!rows[0])throw new ResignationJourneyError('not_found','Resignation not found or unavailable.');return rows[0];}
