const actor=(ctx:SessionContext,c:Context):ResignationLetterActor=>{const u=c.users.find(u=>u.id===ctx.userId);if(!u||!ctx.userId||!ctx.personId)forbidden('Sign in with a linked employee account.');return{userId:ctx.userId,personId:ctx.personId,name:u.name,at:when(),today:todayInKualaLumpur()};};
function notice(c:Context,today:string){return resignationNotice(c,today,c.config?.settlementPolicy);}
function readiness(c:Context,today:string):string|null{try{const read=(key:string)=>({businessGroup:c.businessGroupId,company:c.companyId,department:c.departmentId,jobTitle:c.position,jobGrade:c.jobGrade} as Record<string,string|null>)[key]??null;const workflows=c.workflows??[];const result=decideAutomationRuns(OFFBOARDING_AUTOMATION_CATALOGUE,workflows.map(workflow=>({workflow,revision:1})),{trigger:'submitted',subjectId:'readiness',today,read,anchor:()=>null,skipReason:()=>null});const eligible=new Set(result.decisions.filter(d=>d.outcome==='run').map(d=>d.workflowId));for(const workflow of workflows.filter(w=>eligible.has(w.id))){if(workflow.steps.some(step=>step.type==='requestDecision')){const decision=workflow.steps.find(step=>step.type==='requestDecision');if(decision&&resolve(c,decision.to).some(id=>id!==c.employeeUserId)){resolve(c,Array.isArray(decision.params.watch)?decision.params.watch as AutomationRecipient[]:[]);return null;}}}return 'HR must activate a resignation workflow and assign its decision makers before submissions can open.';}catch{return 'HR must complete the resignation assignment groups and routing rules before submissions can open.';}}
