 r.data.people=names(c,allParticipants(r,c));rebuildTasks(r,c);await prepareResignationProofTx(tx,ctx,{operation:'save',caseId:r.id,revision:r.revision,args:{id:r.id,revision:r.revision,action:permission,stage:r.stage,data:JSON.parse(JSON.stringify(r.data)),participants:allParticipants(r,c),offboarding:r.offboarding_case_id}});const[row]=await tx.execute<{revision:number}>(sql`select app.resignation_journey_save(${r.id}::uuid,${r.revision},${permission},${r.stage},${JSON.stringify(r.data)}::jsonb,${ids(allParticipants(r,c))}::uuid[],${r.offboarding_case_id}::uuid) as revision`);r.revision=row.revision;
