function resolve(c:Context,list:readonly AutomationRecipient[],pending:string[]=[]):string[]{const out:string[]=[];for(const x of list){let found:string[]=[];if(x.kind==='role')found=x.role==='employee'?[c.employeeUserId??'']:x.role==='directSuperior'?[c.supervisorUserId??'']:[];else if(x.kind==='person')found=[x.userId];else if(x.kind==='group')found=c.config?.groups.find(g=>g.id===x.groupId)?.members??[];else if(x.kind==='pending')found=pending;else{const rt=c.routings.find(r=>r.id===x.routingId);if(rt){let match=resolveRoutingRow(rt,{businessGroup:c.businessGroupId,company:c.companyId,department:c.departmentId,jobTitle:c.position});const rowPeople=(row:Routing['rows'][number])=>row.assignTo.kind==='people'?row.assignTo.userIds:c.config?.groups.find(g=>row.assignTo.kind==='group'&&g.id===row.assignTo.groupId)?.members??[];found=match?rowPeople(match.row):[];if(!found.length){const fallback=rt.rows.find(row=>Object.values(row.match).every(v=>!v?.length));if(fallback)found=rowPeople(fallback);}}}found=found.filter(id=>c.users.some(u=>u.id===id));if(!found.length)invalid('Nobody was found for a configured recipient. Check Assignment groups and Routing rules.');out.push(...found);}return[...new Set(out)];}
