export async function commandResignationJourney(ctx:SessionContext,input:ResignationCommandInput):Promise<ResignationCaseView>{assertId(input.caseId);if(!Number.isInteger(input.revision)||input.revision<1)invalid('Reload the resignation before acting.');return mapped(()=>withScopedLifecycleTenant(ctx,async tx=>{
 await prepareResignationProofTx(tx,ctx,{operation:'read',caseId:input.caseId,args:{mode:'case',caseId:input.caseId}});await prepareResignationProofTx(tx,ctx,{operation:'begin',caseId:input.caseId,revision:input.revision,command:input.command,args:{}});const r=await rowTx(tx,input.caseId,true);if(r.revision!==input.revision)throw new ResignationJourneyError('conflict','This resignation changed. Reload before acting.');const c=await context(tx,ctx,r.employment_id,r.id),by=actor(ctx,c),cmd=input.command;const current=freshView(r,ctx,c);
 if(cmd.type==='withdraw'){await assertAction(tx,r.id,'own');if(!current.capabilities.withdraw)forbidden('You cannot withdraw at this stage.');r.stage='withdrawn';r.data.decision=null;r.data.waits=[];r.data.tasks=[];r.data.cancelledRuns=(await automationRunsForSubjectTx(tx,'off',r.id)).filter(run=>['waiting','running','failed'].includes(run.status)).map(run=>run.id);r.data.letters=r.data.letters.map(l=>l.state==='released'?l:{...l,state:'withdrawn'});await fire(tx,ctx,r,c,'withdrawn');}
 else if(cmd.type==='accept'||cmd.type==='offer'){await assertAction(tx,r.id,'decision');const decision=r.data.decision;if(!decision)forbidden();if(cmd.type==='accept'){if(!isCalendarDate(cmd.lastWorkingDay)||cmd.lastWorkingDay<=by.today)invalid('The agreed last working day must be after today.');r.data.lastWorkingDay=cmd.lastWorkingDay;r.data.replacementNeeded=cmd.replacementNeeded;if(cmd.replacementNeeded&&!r.data.replacementRequest){const to=c.config?.groups.find(g=>g.id===c.config?.peopleOpsGroup)?.members.filter(id=>c.users.some(u=>u.id===id))??[];if(!to.length)invalid('Configure an active PeopleOps assignment group before requesting a replacement.');r.data.replacementRequest={id:randomUUID(),status:'requested',requestedOn:by.today,reference:null,completedOn:null,to};}r.stage='accepted';}else{if(!current.capabilities.offer)forbidden(current.offerBlock??'A retention offer is not available.');const o=cmd.offer;if(!o.position?.trim()||o.position.length>200||o.jobGrade.length>80||!/^\d{1,10}(\.\d{1,2})?$/.test(o.basicSalary)||Number(o.basicSalary)<=0||!isCalendarDate(o.effectiveDate)||o.justification.length>4000)invalid('Complete the position, positive basic salary and effective date.');r.data.offer={...o,position:o.position.trim()};r.stage='retention';}r.data.decidedBy={id:by.userId,name:by.name};r.data.decision=null;await save(tx,ctx,r,c,'decision');if(decision.watch.length)await notify(tx,ctx,r,`${decision.id}:recorded`,decision.watch,[],`Decision recorded: resignation of ${c.employeeName}`,cmd.type==='accept'?'The resignation was accepted.':'A retention offer was submitted.');await resumeWait(tx,ctx,r,c,decision.id);await fire(tx,ctx,r,c,cmd.type==='accept'?'accepted':'retention');}
 else if(cmd.type==='comment'){await assertAction(tx,r.id,'comment');if(!cmd.text?.trim()||cmd.text.length>4000)invalid('Write a comment of at most 4000 characters.');r.data.comments.push({id:randomUUID(),by:{id:by.userId,name:by.name},at:by.at,text:cmd.text.trim()});const to=r.data.decision?.to??[];await notify(tx,ctx,r,`comment:${r.data.comments.at(-1)!.id}`,to,[],`New comment on the resignation of ${c.employeeName}`,cmd.text.trim());}
 else if(cmd.type==='approvalTask'){const w=r.data.waits.find(w=>w.kind==='approval'&&w.layers?.some(l=>l.id===cmd.taskId));const layer=w?.layers?.find(l=>!l.done);if(!w||!layer||layer.id!==cmd.taskId||!layer.to.includes(by.userId)||(cmd.action!=='reject'&&layer.action!==cmd.action))forbidden('This approval is not assigned to you.');if((cmd.comment?.length??0)>4000)invalid('Use at most 4000 characters.');if(cmd.action==='reject'&&!cmd.comment?.trim())invalid('Give a reason for rejecting this approval.');if(cmd.action==='reject'){const run=(await automationRunsForSubjectTx(tx,'off',r.id)).find(x=>x.id===w.runId);if(!run||run.status!=='waiting')invalid('This approval workflow is unavailable.');run.status='failed';run.waitingFor=null;run.failure=cmd.comment!.trim();run.log=[...run.log,{at:when(),kind:'failed',step:run.cursor-1,stepId:null,type:'requestApproval',message:run.failure}].slice(-200);await sqlAutomationRunStore(tx).save(run,'waiting');r.data.waits=r.data.waits.filter(x=>x!==w);if(run.trigger==='retention'){r.data.cancelledRuns.push(run.id);r.stage='decision';r.data.offer=null;await fire(tx,ctx,r,c,'rejected');}else{r.data.blocked.push(run.failure);const ops=c.config?.groups.find(g=>g.id===c.config?.peopleOpsGroup)?.members??[];if(ops.length)await notify(tx,ctx,r,`${run.id}:approval-rejected`,ops,[],'Resignation workflow approval rejected',run.failure);}await save(tx,ctx,r,c);return freshView(r,ctx,c);}layer.done=true;if(cmd.comment?.trim())r.data.comments.push({id:randomUUID(),by:{id:by.userId,name:by.name},at:by.at,text:cmd.comment.trim()});const next=w.layers?.find(l=>!l.done);if(next)w.to=next.to;else{r.data.waits=r.data.waits.filter(x=>x!==w);await save(tx,ctx,r,c);await resumeWait(tx,ctx,r,c,w.id);}}
 else if(cmd.type==='completeReplacement'){const request=r.data.replacementRequest;if(!request||request.id!==cmd.taskId||request.status!=='requested'||!request.to.includes(by.userId))forbidden('This recruitment request is not assigned to you.');let url:URL;try{url=new URL(cmd.reference);}catch{invalid('Enter the recruitment request URL.');}if(!['https:','http:'].includes(url!.protocol)||cmd.reference.length>2000)invalid('Enter an http or https recruitment request URL.');request.status='completed';request.reference=url!.toString();request.completedOn=by.today;}
 else if(cmd.type==='updateEmail'){if(!r.data.letters.some(l=>resignationLetterCapabilities(l,by.userId).canEditContent))forbidden('Only the owner holding a letter can edit its email.');if(!c.config?.emails.some(t=>t.id===cmd.emailTemplateId&&t.module==='off')||!cmd.subject.trim()||cmd.subject.length>300||cmd.body.length>100000)invalid('Choose an email and enter a subject and body within the editor limits.');r.data.emailOverrides??={};r.data.emailOverrides[cmd.emailTemplateId]={subject:cmd.subject.trim(),body:cmd.body};}
 else if(cmd.type==='taskProgress'){const t=r.data.tasks.find(t=>t.id===cmd.taskId&&t.userIds.includes(by.userId));if(!t)forbidden();if(!['todo','progress'].includes(cmd.status))invalid('Choose To do or In progress.');r.data.progress[t.id]={status:cmd.status,onIt:t.team?(r.data.progress[t.id]?.onIt??{id:by.userId,name:by.name}):null};}
 else if(cmd.type==='retry'){await assertAction(tx,r.id,'retry');r.data.blocked=[];const runs=await automationRunsForSubjectTx(tx,'off',r.id);for(const run of runs.filter(run=>run.status==='failed'&&(!cmd.runId||run.id===cmd.runId))){const[stored]=await tx.execute<{definition:AutomationWorkflow}>(sql`select definition from automation_workflow_version where tenant_id=${ctx.tenantId}::uuid and workflow_id=${run.workflowId}::uuid and revision=${run.workflowRevision}`);const failed=stored?.definition.steps[run.cursor-1];if(!failed)continue;const next={...run,status:'running' as const,failure:null,waitingFor:null,remaining:[{index:run.cursor-1,step:failed},...run.remaining]};const result=await advanceAutomationRun(next,{executors:await executors(tx,ctx,r,c,{},0),read:readFacts(r,c),now:when});await prepareResignationProofTx(tx,ctx,{operation:'retrySave',caseId:r.id,args:{runId:run.id,result:JSON.parse(JSON.stringify(result))}});await tx.execute(sql`select app.resignation_run_retry_save(${run.id}::uuid,${JSON.stringify(result)}::jsonb)`);}if(!runs.some(x=>x.status==='failed'))await fire(tx,ctx,r,c,r.stage==='decision'?'submitted':r.stage==='retention'?'retention':'accepted');}
 else if('documentId' in cmd){const l=r.data.letters.find(l=>l.id===cmd.documentId);if(!l)throw new ResignationJourneyError('not_found','Letter unavailable.');let action:ResignationLetterAction;if(cmd.type==='openLetter')action={type:'open'};else if(cmd.type==='letterAction'){const step=resignationLetterPendingSteps(l).find(s=>s.holderId===by.userId);if(!step)forbidden();action={type:'complete',stepId:step.id,signature:cmd.signature,consent:cmd.consent,blocks:cmd.blocks};}else if(cmd.type==='sendBack'){const step=resignationLetterPendingSteps(l).find(s=>s.holderId===by.userId);if(!step)forbidden();action={type:'sendBack',stepId:step.id,reason:cmd.reason};}else if(cmd.type==='recall')action={type:'recall'};else if(cmd.type==='resendLetter')action={type:'resend'};else if(cmd.type==='withdrawOffer')action={type:'withdrawOffer',reason:cmd.reason};else if(cmd.type==='declineOffer')action={type:'declineOffer'};else if(cmd.type==='updateLetter'){const caps=resignationLetterCapabilities(l,by.userId);if((cmd.lastWorkingDay!==undefined||cmd.reason!==undefined)&&!caps.canCorrectDetails)forbidden('Only the owner holding the letter can correct case details.');if(cmd.lastWorkingDay!==undefined){if(!isCalendarDate(cmd.lastWorkingDay)||cmd.lastWorkingDay<=by.today)invalid('The last working day must be after today.');r.data.lastWorkingDay=cmd.lastWorkingDay;}if(cmd.reason!==undefined){if(cmd.reason.length>4000)invalid('Use at most 4000 characters for the reason.');r.data.reason=cmd.reason;}if(cmd.blocks)action={type:'edit',blocks:cmd.blocks};else{if(l.revision!==cmd.documentRevision)throw new ResignationJourneyError('conflict','The letter changed.');await applyLetterResult(tx,ctx,r,c,reconcileResignationLetter(l,merge(r,c)));await save(tx,ctx,r,c);return freshView(r,ctx,c);}}else invalid('Unknown letter action.');const result=actResignationLetter(l,{id:randomUUID(),documentRevision:cmd.documentRevision,actor:by,action});await applyLetterResult(tx,ctx,r,c,result);if(cmd.type==='updateLetter')for(const other of [...r.data.letters])if(other.state==='review'||other.state==='owner')await applyLetterResult(tx,ctx,r,c,reconcileResignationLetter(other,merge(r,c)));}
 else invalid('Unknown resignation action.');
 await save(tx,ctx,r,c);return freshView(r,ctx,c);
 }));}
export async function uploadResignationFile(ctx:SessionContext,input:ResignationUploadInput):Promise<ResignationCaseView>{assertId(input.caseId);validateLeaveDocument({allowedMimeTypes:ownMime,maxDocBytes:10485760},{mimeType:input.mimeType,sizeBytes:input.content.byteLength});if(!input.name?.trim()||input.name.length>200)invalid('Choose a named file.');return mapped(()=>withScopedLifecycleTenant(ctx,async tx=>{await prepareResignationProofTx(tx,ctx,{operation:'read',caseId:input.caseId,args:{mode:'case',caseId:input.caseId}});await prepareResignationProofTx(tx,ctx,{operation:'begin',caseId:input.caseId,revision:input.revision,command:{type:'uploadFile',taskId:input.taskId,name:input.name,mimeType:input.mimeType,contentHash:createHash('sha256').update(input.content).digest('hex')},args:{}});const r=await rowTx(tx,input.caseId,true);if(r.revision!==input.revision)throw new ResignationJourneyError('conflict','This task changed. Reload before uploading.');const c=await context(tx,ctx,r.employment_id,r.id),w=r.data.waits.find(w=>w.id===input.taskId&&w.kind==='file');if(!w||!w.to?.includes(ctx.userId??''))forbidden();const hash=createHash('sha256').update(input.content).digest('hex');await tx.execute(sql`insert into resignation_journey_file(tenant_id,case_id,task_id,slot,name,mime_type,size,content,content_hash,uploaded_by) values(${ctx.tenantId}::uuid,${r.id}::uuid,${w.id},${w.slot??''},${input.name},${input.mimeType},${input.content.byteLength},${Buffer.from(input.content)},${hash},${ctx.userId}::uuid)`);const runs=await automationRunsForSubjectTx(tx,'off',r.id),run=runs.find(run=>run.id===w.runId);const step=(w as Wait&{step:AutomationStep}).step;if(!run||!step)invalid('The upload workflow is unavailable.');const ex=await executors(tx,ctx,r,c,{},0),out=await ex.sendEmail!({run,step,index:run.cursor-1,read:readFacts(r,c)});if(out.status==='done'){r.data.waits=r.data.waits.filter(x=>x!==w);await resumeWait(tx,ctx,r,c,w.id);}else if(out.status==='failed')r.data.blocked.push(out.reason);await save(tx,ctx,r,c);return freshView(r,ctx,c);}));}
export async function downloadResignationLetter(ctx:SessionContext,input:{caseId:string;documentId:string}):Promise<{name:string;content:Uint8Array}>{const row=await resignationCase(ctx,input.caseId),letter=row.letters.find(l=>l.id===input.documentId);if(!letter?.document||letter.state!=='released'||letter.private)throw new ResignationJourneyError('not_found','Released letter unavailable.');const{renderV9DocumentPdf}=await import('../lib/lifecycle-v9-pdf');const out=await renderV9DocumentPdf(letter.document,row.number);return{name:letter.name.replace(/[^\p{L}\p{N} ._()-]/gu,'_')+'.pdf',content:out.bytes};}
export async function resumeResignationPostingTx(tx:Tx,ctx:SessionContext,journeyId:string,postingId:string,outcome:'approved'|'rejected',reason?:string):Promise<void>{await prepareResignationProofTx(tx,ctx,{operation:'read',caseId:journeyId,args:{mode:'case',caseId:journeyId}});const r=await rowTx(tx,journeyId,true),c=await context(tx,ctx,r.employment_id,r.id),w=r.data.waits.find(w=>w.kind==='posting'&&w.id===postingId);if(!w)return;await prepareResignationProofTx(tx,ctx,{operation:'begin',caseId:journeyId,revision:r.revision,command:{type:'postingOutcome',postingId,outcome,reason:reason??null},args:{}});const[proof]=await tx.execute<{status:string}>(sql`select status from personnel_posting where tenant_id=${ctx.tenantId}::uuid and id=${postingId}::uuid and source='offboarding' and source_ref=${journeyId}::uuid`);if(!proof||proof.status!==outcome)forbidden('The posting outcome is not recorded.');if(outcome==='approved'){r.data.waits=r.data.waits.filter(x=>x!==w);await resumeWait(tx,ctx,r,c,postingId);}else{w.blocked=reason??'The Personnel posting was rejected.';r.data.blocked.push(w.blocked);await prepareResignationProofTx(tx,ctx,{operation:'postingRejected',caseId:r.id,args:{runId:w.runId,postingId,reason:w.blocked}});await tx.execute(sql`select app.resignation_posting_run_rejected(${w.runId}::uuid,${postingId}::uuid,${w.blocked})`);}await save(tx,ctx,r,c);}
export async function resignationConfigurationCases(ctx:SessionContext,opts:{search?:string;limit?:number}={}):Promise<{id:string;number:string;employeeName:string;employeeCode:string}[]>{return withScopedLifecycleTenant(ctx,async tx=>{const[ok]=await tx.execute<{ok:boolean}>(sql`select app.automation_can_configure('off') as ok`);if(!ok?.ok)forbidden();await prepareResignationProofTx(tx,ctx,{operation:'read',args:{mode:'configuration',companyIds:[]}});const query=(opts.search??'').trim().slice(0,100);return[...await tx.execute<{id:string;number:string;employeeName:string;employeeCode:string}>(sql`select id,'RSN-'||lpad(number::text,4,'0') as number,data->'facts'->>'employeeName' as "employeeName",data->'facts'->>'employeeCode' as "employeeCode" from resignation_journey where tenant_id=${ctx.tenantId}::uuid and (${query}='' or data->'facts'->>'employeeName' ilike ${'%'+query+'%'} or data->'facts'->>'employeeCode' ilike ${'%'+query+'%'}) order by number desc limit ${Math.min(20,Math.max(1,opts.limit??20))}`)];});}
export async function resignationWorkflowDryRun(ctx:SessionContext,input:{workflow:AutomationWorkflow;caseId:string}){return withScopedLifecycleTenant(ctx,async tx=>{const[ok]=await tx.execute<{ok:boolean}>(sql`select app.automation_can_configure('off') as ok`);if(!ok?.ok||input.workflow.module!=='off')forbidden();await prepareResignationProofTx(tx,ctx,{operation:'read',caseId:input.caseId,args:{mode:'case',caseId:input.caseId}});const r=await rowTx(tx,input.caseId),c=await context(tx,ctx,r.employment_id,r.id);return{employeeName:c.employeeName,run:dryRunAutomationWorkflow(input.workflow,OFFBOARDING_AUTOMATION_CATALOGUE,{read:readFacts(r,c),anchor:()=>null,skipReason:s=>s==='caseClosed'&&CLOSED.has(r.stage)?'the case is closed':null,resolve:x=>{try{return{names:names(c,resolve(c,[x])).map(p=>p.name),missing:null};}catch(e){return{names:[],missing:e instanceof Error?e.message:'Nobody found.'};}}})};});}
/** Explicit setup action: preserves every existing definition, including retired and customized copies. */
export async function installResignationDefaults(ctx:SessionContext):Promise<{workflows:number;templates:number;emails:number}>{
 const {v9SaveConfig}=await import('../packs/lifecycle/v9/service');const{installAutomationDefaults}=await import('./automation-builder');const{resignationDefaults}=await import('../lib/resignation-defaults');
 const current=await withScopedLifecycleTenant(ctx,async tx=>{const[ok]=await tx.execute<{ok:boolean}>(sql`select app.automation_can_configure('off') as ok`);if(!ok?.ok)forbidden();const[row]=await tx.execute<{data:Config}>(sql`select data from lc_v9_config where tenant_id=${ctx.tenantId}::uuid`);if(!row)invalid('Open Onboarding & offboarding settings first.');const[user]=await tx.execute<{name:string}>(sql`select p.full_name as name from app_user u join person p on p.id=u.person_id and p.tenant_id=u.tenant_id where u.id=${ctx.userId}::uuid and u.tenant_id=${ctx.tenantId}::uuid`);return{config:row.data,name:user?.name??'Configuration administrator'};});
 const defaults=resignationDefaults(current.config,current.name,when()),templates=defaults.templates.filter(t=>!current.config.templates.some(x=>x.id===t.id)),emails=defaults.emails.filter(t=>!current.config.emails.some(x=>x.id===t.id));
 if(templates.length||emails.length)await v9SaveConfig(ctx,current.config.revision,{...current.config,templates:[...current.config.templates,...templates],emails:[...current.config.emails,...emails]});
 const result=await installAutomationDefaults(ctx,{workflows:defaults.workflows,emailTemplates:[],routings:defaults.routings});return{workflows:result.installed.workflows,templates:templates.length,emails:emails.length};
}
export async function readResignationJourneyAttachment(ctx:SessionContext,input:{caseId:string;attachmentId:string}):Promise<{fileName:string;mimeType:string;content:Buffer}>{assertId(input.attachmentId);return withScopedLifecycleTenant(ctx,async tx=>{await prepareResignationProofTx(tx,ctx,{operation:'read',caseId:input.caseId,args:{mode:'case',caseId:input.caseId}});const r=await rowTx(tx,input.caseId);if(!r.data.attachments.some(a=>a.id===input.attachmentId))throw new ResignationJourneyError('not_found','Attachment unavailable.');const[row]=await tx.execute<{fileName:string;mimeType:string;content:Buffer}>(sql`select file_name as "fileName",mime_type as "mimeType",content from resignation_request_attachment where tenant_id=${ctx.tenantId}::uuid and resignation_request_id=${r.id}::uuid and id=${input.attachmentId}::uuid`);if(!row)throw new ResignationJourneyError('not_found','Attachment unavailable.');return row;});}
/** Minute worker catches up each due occurrence once, at/after 08:00 Malaysia and on the employee's working calendar. */
export async function sweepResignationJourneys(ctx:SessionContext,connection:import('./notice-projection').NotificationSweepConnection,now=new Date()):Promise<{processed:number;failed:number}>{
 if(ctx.userId||timeInKualaLumpur(now)<'08:00')return{processed:0,failed:0};const today=todayInKualaLumpur(now);
 const due=await connection.withTenant(ctx,async tx=>{const[owner]=await tx.execute<{ok:boolean}>(sql`select current_user='ai_hr_owner' or exists(select 1 from pg_roles where rolname=current_user and rolsuper) as ok`);if(!owner?.ok)forbidden('Scheduling requires the storage owner.');return tx.execute<{id:string}>(sql`select id from resignation_journey where tenant_id=${ctx.tenantId}::uuid and stage='offer' and ((data->>'offerReplyBy'<${today}) or (data->>'offerRemindOn'<=${today} and not coalesce((data->>'offerReminded')::boolean,false))) order by updated_at,id limit 200`);});
 const out={processed:0,failed:0};for(const{id}of due)try{await connection.withTenant(ctx,async tx=>{const r=await rowTx(tx,id,true);await prepareResignationProofTx(tx,ctx,{operation:'begin',caseId:id,revision:r.revision,command:{type:'sweep'},args:{}});if(r.stage!=='offer')return;const c=await context(tx,ctx,r.employment_id,r.id);const weekday=new Date(today+'T00:00:00Z').getUTCDay();if(weekday===0||weekday===6)return;const holidays=await holidayDatesFor(tx,{employmentId:r.employment_id,startDate:today,endDate:today});if(holidays.has(today))return;
 if(r.data.offerReplyBy&&today>r.data.offerReplyBy){const letter=r.data.letters.find(l=>l.kind==='retention'&&resignationLetterEmployeePending(l));if(letter)await applyLetterResult(tx,ctx,r,c,lapseResignationLetter(letter));}
 else if(r.data.offerRemindOn&&today>=r.data.offerRemindOn&&!r.data.offerReminded){r.data.offerReminded=true;await fire(tx,ctx,r,c,'offerDue');}await save(tx,ctx,r,c);});out.processed++;}catch{out.failed++;}return out;
}
